package com.aaliyun.leadnews.schedule.config;import com.aaliyun.leadnews.common.persistence.AuditMetaObjectHandler;import com.baomidou.mybatisplus.extension.plugins.*;import com.baomidou.mybatisplus.extension.plugins.inner.OptimisticLockerInnerInterceptor;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.*;
@Configuration @EnableConfigurationProperties(ScheduleProperties.class)public class ScheduleConfiguration{@Bean MybatisPlusInterceptor interceptor(){MybatisPlusInterceptor i=new MybatisPlusInterceptor();i.addInnerInterceptor(new OptimisticLockerInnerInterceptor());return i;}@Bean AuditMetaObjectHandler audit(){return new AuditMetaObjectHandler();}}
